CREATE TABLE IF NOT EXISTS partner_profiles (id INT AUTO_INCREMENT PRIMARY KEY,person_id INT NOT NULL UNIQUE,user_id INT NOT NULL UNIQUE,status VARCHAR(30) NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(person_id) REFERENCES people(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS partner_company_access (id INT AUTO_INCREMENT PRIMARY KEY,partner_id INT NOT NULL,company_id INT NOT NULL,relationship_type VARCHAR(60) NOT NULL DEFAULT 'Partner',ownership_percent DECIMAL(7,4) NOT NULL DEFAULT 0,notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_partner_company(partner_id,company_id),FOREIGN KEY(partner_id) REFERENCES partner_profiles(id) ON DELETE CASCADE,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS partner_investments (id INT AUTO_INCREMENT PRIMARY KEY,partner_id INT NOT NULL,company_id INT NOT NULL,investment_date DATE NOT NULL,investment_type VARCHAR(60) NOT NULL DEFAULT 'Capital contribution',amount DECIMAL(15,2) NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'INR',reference_no VARCHAR(180),notes TEXT,created_by INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(partner_id) REFERENCES partner_profiles(id) ON DELETE CASCADE,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS partner_tasks (id INT AUTO_INCREMENT PRIMARY KEY,partner_id INT NOT NULL,company_id INT NULL,title VARCHAR(220) NOT NULL,description TEXT,due_date DATE,priority VARCHAR(20) NOT NULL DEFAULT 'Medium',status VARCHAR(30) NOT NULL DEFAULT 'pending',created_by INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(partner_id) REFERENCES partner_profiles(id) ON DELETE CASCADE,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
